// never enter the diagnostic record. Devsy uses the last valid repeated flag.
fn diagnostic_clone_strategy(args : Array[String]) -> (String, String) {
  let mut strategy = "full"
  let mut count = 0
  let mut invalid = false
  let mut index = 0
  while index < args.length() {
    let argument = args[index]
    let value = if argument == "--git-clone-strategy" {
      count += 1
      index += 1
      if index < args.length() { Some(args[index]) } else { None }
    } else if argument.has_prefix("--git-clone-strategy=") {
      count += 1
      Some(argument[21:].to_owned())
    } else { None }
    if count > 0 && (argument == "--git-clone-strategy" || argument.has_prefix("--git-clone-strategy=")) {
      match value {
        Some("") => strategy = "full"
        Some("shallow" | "blobless" | "treeless" | "bare" as known) => strategy = known
        _ => invalid = true
      }
    }
    index += 1
  }
  (if invalid { "invalid" } else { strategy }, if count > 1 { "upArgs" } else { "adapter" })
}
